fn max_aggregate(stdata: [(str, int)]) -> (str, int):
    """
    Write a function to calculate the maximum aggregate from the list of tuples.
    """
    var totals: {str: int} = {}
    var order: [str] = []
    for item in stdata:
        name, score = item
        if name in totals:
            totals[name] = totals[name] + score
        else:
            totals[name] = score
            order.append(name)
    var best_name = ""
    var best_total = 0
    var found = False
    for name in order:
        total = totals[name]
        if not found or total > best_total:
            best_name = name
            best_total = total
            found = True
    return (best_name, best_total)

